/* Generated by equipe-design emit — do not edit by hand; change the tokens and emit again. */
/* Light is the default. Dark follows prefers-color-scheme and can be forced with <html data-theme="dark|light">. */
:root {
  color-scheme: light dark;
  /* color */
  --eq-color-background: #f6f5f1;
  --eq-color-surface: #ecebe7;
  --eq-color-raised: #f1f0ec;
  --eq-color-text: #15161a;
  --eq-color-muted-text: #656567;
  --eq-color-primary: #1d4ed8;
  --eq-color-on-primary: #ffffff;
  --eq-color-secondary: #e4e3e0;
  --eq-color-accent: #1d4ed8;
  --eq-color-border: #d0cfcc;
  --eq-color-border-strong: #707072;
  --eq-color-ring: #1d4ed8;
  --eq-color-destructive: #c62828;
  --eq-color-success: #1b7a43;
  --eq-color-warning: #8f5b00;

  /* font */
  --eq-font-family-sans: 'Inter Variable', system-ui, sans-serif;
  --eq-font-family-mono: 'JetBrains Mono Variable', ui-monospace, monospace;
  --eq-font-weight-regular: 400;
  --eq-font-weight-semibold: 600;
  --eq-font-weight-bold: 700;

  /* space */
  --eq-space-1: 4px;
  --eq-space-2: 8px;
  --eq-space-3: 12px;
  --eq-space-4: 16px;
  --eq-space-5: 24px;
  --eq-space-6: 32px;
  --eq-space-7: 48px;
  --eq-space-8: 72px;
  --eq-space-9: 112px;

  /* radius */
  --eq-radius-sm: 6px;
  --eq-radius-md: 8px;
  --eq-radius-lg: 16px;
  --eq-radius-xl: 24px;
  --eq-radius-full: 9999px;

  /* shadow */
  --eq-shadow-1: 0px 8px 24px 0px #15161a14;

  /* motion */
  --eq-duration-fast: 160ms;
  --eq-duration-base: 160ms;
  --eq-duration-slow: 160ms;

  /* motion */
  --eq-easing-standard: cubic-bezier(0.2, 0, 0, 1);

  /* z-index */
  --eq-z-1: 50;

  /* type roles: weight size/line-height family */
  --eq-type-display: 600 56px/1.05 var(--eq-font-family-sans);
  --eq-type-display-tracking: -0.02em;
  --eq-type-h1: 700 40px/1.15 var(--eq-font-family-sans);
  --eq-type-h1-tracking: -0.015em;
  --eq-type-h2: 600 32px/1.2 var(--eq-font-family-sans);
  --eq-type-h2-tracking: -0.01em;
  --eq-type-h3: 600 24px/1.3 var(--eq-font-family-sans);
  --eq-type-h3-tracking: 0em;
  --eq-type-body: 400 16px/1.5 var(--eq-font-family-sans);
  --eq-type-body-tracking: 0em;
  --eq-type-small: 400 14px/1.5 var(--eq-font-family-sans);
  --eq-type-small-tracking: 0em;
  --eq-type-mono: 400 14px/1.5 var(--eq-font-family-mono);
  --eq-type-mono-tracking: 0em;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --eq-color-background: #0a0a0c;
    --eq-color-surface: #141416;
    --eq-color-raised: #1c1c1d;
    --eq-color-text: #efede7;
    --eq-color-muted-text: #898886;
    --eq-color-primary: #8fb0ff;
    --eq-color-on-primary: #000000;
    --eq-color-secondary: #161618;
    --eq-color-accent: #8fb0ff;
    --eq-color-border: #232324;
    --eq-color-border-strong: #7d7c7a;
    --eq-color-ring: #8fb0ff;
    --eq-color-destructive: #ff8a80;
    --eq-color-success: #5fd68f;
    --eq-color-warning: #f0b44c;
  }
}
:root[data-theme="light"] { color-scheme: light; }
:root[data-theme="dark"] {
  color-scheme: dark;
  --eq-color-background: #0a0a0c;
  --eq-color-surface: #141416;
  --eq-color-raised: #1c1c1d;
  --eq-color-text: #efede7;
  --eq-color-muted-text: #898886;
